@Configuration
public class TomcatConfig {

    @Bean
    public WebServerFactoryCustomizer<TomcatServletWebServerFactory> customizer() {
        return factory -> {
            factory.addConnectorCustomizers(connector -> {
                var protocol = (Http11NioProtocol) connector.getProtocolHandler();
                protocol.setMaxThreads(250); // same as property, shown for clarity
                protocol.setKeepAliveTimeout(60000); // 60 seconds
                protocol.setMaxKeepAliveRequests(100);
            });
        };
    }
}

