@Component
class ServerLifecycleListener {

    @EventListener
    public void onApplicationReady(ApplicationReadyEvent event) {
        // Fired AFTER server has started and is ready for traffic
        System.out.println("Application ready to serve requests");
    }

    @EventListener
    public void onServerInitialized(ServletWebServerInitializedEvent event) {
        int port = event.getWebServer().getPort();
        System.out.println("Embedded server started on port " + port);
    }

    @PreDestroy
    public void onShutdown() {
        // Called during ApplicationContext close, before resources released
        System.out.println("Application shutting down, cleaning up resources");
    }
}

